<template><div><h2>信号优化分析</h2><el-card><el-form inline><el-form-item label="任务 ID"><el-input v-model="taskId" /></el-form-item><el-form-item><el-button type="primary" @click="calculate">计算候选方案</el-button></el-form-item></el-form></el-card><el-card class="panel"><el-table :data="items"><el-table-column prop="cycle" label="周期"/><el-table-column prop="offset" label="相位差"/><el-table-column prop="delay" label="平均延误"/><el-table-column prop="queue" label="排队长度"/><el-table-column prop="score" label="评分"/></el-table></el-card></div></template><script setup lang="ts">import {ref} from 'vue';import {api} from '../../api';const taskId=ref('optimization-demo');const items=ref<Record<string,unknown>[]>([]);const calculate=async()=>{const r=await api.optimize({taskId:taskId.value,baseCycle:120,baseOffset:20});items.value=r.data.data.items||[]}</script>
